window.kbPageData["cards/d3836bc80f0527514316feea"] = {"qs":{"国考 2023 行政执法 行测#51":{"paper":"国考 2023 行政执法 行测","n":51,"mod":"言语理解与表达","src":["857378cf496f27296500.pdf",8],"asrc":["d23139fe5a0fb3115135.pdf",16],"m":[],"task":"根据并列提示和上下句的话题关系，排列讨论生鲜电商竞争的六个句子。","current_affairs":{"state":"否","event":null,"year":null,"basis":"语序可由句内的并列提示和话题关系确定。"},"links":[{"id":"s-871196fcda246b8d","label":"排列语句顺序","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"①句出现“同样”，表示并列关系","why":"需用“同样”定位另一处介绍企业竞争优势的句子，再据此判断语序。","origin":"逐题标记","originalId":"s-ed17edf157e161a5"}],"stem":"①同样，市场规模更大的企业将能够更好地摊薄其供应链成本，从而在低毛利环境中生存下来，打败竞争对手\n②有些生鲜平台称呼其商业模式为“自来水模式”，立志要让好的食材像自来水一样，触手可得\n③在互联网领域，生鲜电商能否盈利不是问题，谁能成为最后的赢家才是问题\n④由于生鲜电商平台具备很强的消费者粘性，先占据更多核心区消费者的企业便能获得先发优势，后进入者往往需\n要付出更高的获客成本\n⑤这种现象在经济学上被称作“自然垄断”，即某些产品和服务由单个企业大规模生产经营比多个企业同时生产经营更\n有效率\n⑥而“自来水行业”便是自然垄断最普遍出现的行业\n将以上6个句子重新排列，语序正确的是：","options":["②⑤⑥①④③","②④⑤①③⑥","④①⑤②⑥③","④⑤③①②⑥"],"answer":"C","analysis":"51. 正确答案：C\n\n解析：\n对比选项，确定首句。②句指出有些生鲜平台的商业模式为“自来水模式”，④句指出消费者对生鲜电商平台非常重\n要，均可作首句。\n继续观察文段，①句出现“同样”，表示并列关系，可寻找捆绑关系，①句指出市场规模更大的企业能够减少成本，从\n而打败竞争对手，故前文应介绍企业在竞争中能够成为赢家的其他优势。结合选项分析，①句前分别是③④⑤⑥四\n句，④句指出拥有更多消费者的企业能获得先发优势，故④①两句均介绍了企业能够打败竞争对手、成为赢家的优\n势，可构成并列关系，而③句指出生鲜电商面临的问题，⑤句介绍了“自然垄断”这一概念，⑥句介绍了自然垄断最普\n遍出现的行业是“自来水行业”，均无法和①句构成捆绑，排除A、B、D三项，锁定C项。\n故正确答案为C。\n【文段出处】《谁是赢家？生鲜电商的崛起》\n【考点】\n并列","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false},"国考 2024 副省级 行测#46":{"paper":"国考 2024 副省级 行测","n":46,"mod":"言语理解与表达","src":["a566fec37e508ca7f975.pdf",8],"asrc":["a475ecf57d968bc14cd6.pdf",15],"m":[],"task":"按荒漠化概况、危害、治理现状、形势判断和应对要求之间的衔接重排六个句子。","current_affairs":{"state":"否","event":null,"year":null,"basis":"句间衔接可由题内信息判断，讲话背景无需另行识别。"},"links":[{"id":"s-871196fcda246b8d","label":"按行文逻辑排列语句","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"应先引出“荒漠化”的话题，再论述其防治的情况","why":"先由荒漠化概况引出危害，再串联治理进展和沙尘天气变化，最后用“现实表明”归纳形势并接续应对要求。","origin":"逐题标记","originalId":"s-d589e92b95c871bb"}],"stem":"①当前，我国荒漠化、沙化土地治理呈现出“整体好转、改善加速”的良好态势，但沙化土地面积大、分布广、程\n度重、治理难的基本面尚未根本改变\n②现实表明，我国荒漠化防治和防沙治沙工作形势依然严峻\n③我国是世界上荒漠化最严重的国家之一，荒漠化土地主要分布在三北地区，而且荒漠化地区与经济欠发达区、少\n数民族聚居区等高度耦合\n④荒漠化、风沙危害和水土流失导致的生态灾害，制约着三北地区经济社会发展，对中华民族的生存、发展构成挑\n战\n⑤我们要充分认识防沙治沙工作的长期性、艰巨性、反复性和不确定性，进一步提高站位，增强使命感和紧迫感\n⑥这两年，受气候变化异常影响，我国北方沙尘天气次数有所增加\n将以上6个句子重新排列，语序正确的一项是：","options":["①③⑥⑤②④","②⑤⑥①④③","④①③②⑥⑤","③④①⑥②⑤"],"answer":"D","analysis":"46. 正确答案：D\n解析：\n对比选项，确定首句。①句和②句均介绍我国的荒漠化、沙化土地的防治情况。③句介绍我国是荒漠化最严重的国\n家之一及我国荒漠化土地的主要分布地区，引出我国“荒漠化”这一话题。根据逻辑顺序，应先引出“荒漠化”的话题，\n再论述其防治的情况，故③句应在①句和②句之前，锁定D项。\n验证D项的逻辑，③句引出“我国是荒漠化最严重的国家之一”这一话题，接着④句介绍荒漠化影响着生态及经济等的\n发展，随后①句介绍荒漠化经过治理虽有好转，但根本问题依然存在，⑥句通过近两年我国北方沙尘天气次数增加\n对前文进行论证，接着通过②句再次指出我国的荒漠化及沙化防治形势严峻，最后⑤句给出对策，我们要认识到防\n沙治沙工作的特性，提高站位，增强使命感和紧迫感，逻辑通顺，当选。\n故正确答案为D。\n【文段出处】国家林业和草原局《习近平在内蒙古巴彦淖尔考察并主持召开加强荒漠化综合防治和推进“三北”等重点\n生态工程建设座谈会》\n【考点】\n问题+对策,行文逻辑-其他","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false},"国考 2024 副省级 行测#47":{"paper":"国考 2024 副省级 行测","n":47,"mod":"言语理解与表达","src":["a566fec37e508ca7f975.pdf",8],"asrc":["a475ecf57d968bc14cd6.pdf",15],"m":[],"task":"按全链条食物损耗、损耗数据、消费环节、减损收益和总体对策之间的衔接重排六个句子。","current_affairs":{"state":"否","event":null,"year":null,"basis":"统计数字和减损措施均为题内语句排序的材料。"},"links":[{"id":"s-871196fcda246b8d","label":"按行文逻辑排列语句","catalog_id":null,"type":null,"role":"直接考查","field":"answer","quote":"应先指出问题再提出对策","why":"先由各环节的普遍损耗引出总量数据，再聚焦消费环节，用消费数据承接健康饮食，最后归纳减损收益并提出全链条对策。","origin":"逐题标记","originalId":"s-d589e92b95c871bb"}],"stem":"①据有关机构估算，每年损失浪费的食物超过22.7%，约9200亿斤，若能挽回一半的损失，就够1.9亿人吃一年\n②食物节约减损既可有效减轻供给压力，也可减少资源使用，善莫大焉\n③我国居民食用油和“红肉”人均消费量，分别超过膳食指南推荐标准约1倍和2倍\n④当前，食物采收、储运、加工、销售、消费每个环节都有“跑冒滴漏”，情况还相当严重\n⑤要树立节约减损就是增产的理念，推进全链条节约减损，健全常态化、长效化工作机制，每个环节都要有具体抓\n手，越是损失浪费严重的环节越要抓得实\n⑥消费环节大有文章可做，不仅要制止“舌尖上的浪费”，深入开展“光盘行动”，还要提倡健康饮食\n将以上6个句子重新排列，语序正确的一项是：","options":["①⑥③②④⑤","①③④⑤②⑥","④①⑥③②⑤","④②⑤③①⑥"],"answer":"C","analysis":"47. 正确答案：C\n解析：\n对比选项，确定首句。首句分别为①句和④句，④句指出食物的每个环节都有“跑冒滴漏”的现象存在，即引出食物损\n失浪费的话题，①句通过数据具体分析了我国每年损失浪费食物的现象十分严重，根据逻辑顺序，应先引出食物损\n失浪费的话题再具体分析，故④句更适合作首句，保留C、D两项，排除A、B两项。\n观察对比C、D两项，判断④句之后接①句还是②句，①句具体分析了我国每年损失浪费食物的现象十分严重，与④\n句话题一致，衔接恰当，②句提出“食物节约减损”即针对食物损失浪费的问题提出对策，根据逻辑顺序，应先指出问\n题再提出对策，故②句应在①句之后，排除D项，C项当选。\n故正确答案为C。\n【文段出处】《习近平：加快建设农业强国 推进农业农村现代化》\n【考点】\n背景引入,问题+对策","figs":[],"state":"已标记","notes":[],"domains":["汉语"],"nature":"技能题","current":false}},"materialFiles":{},"terms":{"s-871196fcda246b8d":{"id":"s-871196fcda246b8d","mode":"s","type":"言语理解与表达","title":"语句排序与插入","qs":[],"count":26}},"questions":{}};
